import * as React from 'react'
import { Input } from '@/components/ui/input'
import { useControllableState } from '@/components/ui/util'
import { colorChannels, channelsToHex, type ColorFormat } from '@/lib/color'
export function ColorPicker({
  value,
  defaultValue = '#e66043',
  onValueChange,
  presets = ['#e66043', '#3b82f6', '#8b5cf6', '#10b981', '#f59e0b', '#18181b'],
  disabled,
  allowAlpha = false,
  format: controlledFormat,
}: {
  value?: string
  defaultValue?: string
  onValueChange?: (color: string) => void
  presets?: string[]
  disabled?: boolean
  allowAlpha?: boolean
  format?: ColorFormat
}) {
  const [color, setColor] = useControllableState({ value, defaultValue, onChange: onValueChange })
  const safe = /^#[0-9a-f]{6}([0-9a-f]{2})?$/i.test(color) ? color : '#e66043'
  const [draft, setDraft] = React.useState(safe)
  const [internalFormat, setFormat] = React.useState<ColorFormat>(controlledFormat ?? 'hex'),
    format = internalFormat
  React.useEffect(() => setDraft(safe), [safe])
  const alpha = safe.length === 9 ? parseInt(safe.slice(7, 9), 16) / 255 : 1
  return (
    <div className="inline-flex flex-col gap-3">
      <div className="flex items-center gap-2">
        <input
          aria-label="Choose a color"
          type="color"
          className="h-9 w-10 cursor-pointer rounded border bg-transparent p-1"
          value={safe.slice(0, 7)}
          disabled={disabled}
          onChange={(e) =>
            setColor(e.target.value + (allowAlpha && alpha < 1 ? safe.slice(7) : ''))
          }
        />
        {format === 'hex' ? (
          <Input
            aria-label="Hex color"
            className="w-32 font-mono"
            value={draft}
            disabled={disabled}
            onChange={(e) => {
              setDraft(e.target.value)
              if (
                (allowAlpha ? /^#[0-9a-f]{6}([0-9a-f]{2})?$/ : /^#[0-9a-f]{6}$/).test(
                  e.target.value.toLowerCase(),
                )
              )
                setColor(e.target.value)
            }}
            onBlur={() => setDraft(safe)}
          />
        ) : (
          <div className="flex gap-1">
            {colorChannels(safe, format).map((channel, index) => (
              <Input
                key={index}
                aria-label={`${format.toUpperCase()} ${index + 1}`}
                type="number"
                className="w-16 px-2"
                value={Math.round(channel)}
                min={0}
                max={format === 'rgb' ? 255 : index === 0 ? 360 : 100}
                disabled={disabled}
                onChange={(e) => {
                  const channels = colorChannels(safe, format)
                  channels[index] = Number(e.target.value)
                  setColor(
                    channelsToHex(channels, format) +
                      (allowAlpha && alpha < 1 ? safe.slice(7) : ''),
                  )
                }}
              />
            ))}
          </div>
        )}
        <select
          aria-label="Color display format"
          className="h-9 rounded border bg-background px-2 text-xs"
          value={format}
          onChange={(e) => setFormat(e.target.value as ColorFormat)}
        >
          <option value="hex">HEX</option>
          <option value="rgb">RGB</option>
          <option value="hsl">HSL</option>
          <option value="hsb">HSB</option>
        </select>
      </div>
      {allowAlpha && (
        <label className="flex items-center gap-3 text-xs text-muted-foreground">
          Opacity
          <input
            type="range"
            aria-label="Color opacity"
            min={0}
            max={100}
            value={Math.round(alpha * 100)}
            disabled={disabled}
            onChange={(e) =>
              setColor(
                safe.slice(0, 7) +
                  Math.round(Number(e.target.value) * 2.55)
                    .toString(16)
                    .padStart(2, '0'),
              )
            }
            className="min-w-20 flex-1 accent-primary"
          />
          <span className="w-8 text-right">{Math.round(alpha * 100)}%</span>
        </label>
      )}
      <div className="flex gap-2">
        {presets.map((p) => (
          <button
            key={p}
            type="button"
            disabled={disabled}
            aria-label={`Use ${p}`}
            aria-pressed={p === safe}
            onClick={() => setColor(p)}
            className="size-5 rounded-full border-2 border-background shadow-sm outline-offset-2 aria-pressed:outline-2 aria-pressed:outline-ring"
            style={{ background: p }}
          />
        ))}
      </div>
    </div>
  )
}
export interface GradientValue {
  from: string
  to: string
  angle: number
  stops?: { color: string; position: number }[]
}
export function GradientPicker({
  value,
  defaultValue = { from: '#e66043', to: '#8b5cf6', angle: 120 },
  onValueChange,
  disabled,
}: {
  value?: GradientValue
  defaultValue?: GradientValue
  onValueChange?: (gradient: GradientValue) => void
  disabled?: boolean
}) {
  const [gradient, set] = useControllableState({ value, defaultValue, onChange: onValueChange })
  return (
    <div className="max-w-lg space-y-4">
      <div
        className="h-20 rounded-lg border"
        style={{
          background: `linear-gradient(${gradient.angle}deg,${
            gradient.stops?.length
              ? [...gradient.stops]
                  .sort((a, b) => a.position - b.position)
                  .map((stop) => `${stop.color} ${stop.position}%`)
                  .join(',')
              : `${gradient.from},${gradient.to}`
          })`,
        }}
      />
      {gradient.stops?.length ? (
        <div className="space-y-2">
          {gradient.stops.map((stop, index) => (
            <div key={index} className="flex flex-wrap items-center gap-3">
              <ColorPicker
                value={stop.color}
                disabled={disabled}
                onValueChange={(color) =>
                  set({
                    ...gradient,
                    stops: gradient.stops!.map((item, i) =>
                      i === index ? { ...item, color } : item,
                    ),
                  })
                }
                allowAlpha
              />
              <Input
                aria-label={`Stop ${index + 1} position`}
                className="w-20"
                type="number"
                min={0}
                max={100}
                value={stop.position}
                disabled={disabled}
                onValueChange={(value) =>
                  set({
                    ...gradient,
                    stops: gradient.stops!.map((item, i) =>
                      i === index
                        ? { ...item, position: Math.max(0, Math.min(100, Number(value))) }
                        : item,
                    ),
                  })
                }
              />
              <button
                disabled={disabled || gradient.stops!.length <= 2}
                className="text-xs text-destructive"
                onClick={() =>
                  set({ ...gradient, stops: gradient.stops!.filter((_, i) => i !== index) })
                }
              >
                Remove stop
              </button>
            </div>
          ))}
          <button
            disabled={disabled}
            className="text-xs text-primary"
            onClick={() =>
              set({ ...gradient, stops: [...gradient.stops!, { color: '#6976c5', position: 50 }] })
            }
          >
            Add stop
          </button>
        </div>
      ) : (
        <div className="flex flex-wrap gap-5">
          <ColorPicker
            value={gradient.from}
            onValueChange={(from) => set({ ...gradient, from })}
            allowAlpha
          />
          <ColorPicker
            value={gradient.to}
            onValueChange={(to) => set({ ...gradient, to })}
            allowAlpha
          />
        </div>
      )}
      <label className="flex items-center gap-3 text-xs text-muted-foreground">
        Angle
        <input
          aria-label="Gradient angle"
          type="range"
          min={0}
          max={360}
          value={gradient.angle}
          className="flex-1 accent-primary"
          onChange={(e) => set({ ...gradient, angle: Number(e.target.value) })}
        />
        {gradient.angle}°
      </label>
    </div>
  )
}

import * as React from 'react'
import { Eye, EyeOff, X } from 'lucide-react'
import { cn } from '@/lib/utils'
import { useControllableState } from '@/components/ui/util'
export interface InputProps extends Omit<React.ComponentProps<'input'>, 'prefix'> {
  leading?: React.ReactNode
  trailing?: React.ReactNode
  allowClear?: boolean
  showCount?: boolean
  passwordToggle?: boolean
  onValueChange?: (value: string) => void
}
export function Input({
  className,
  type = 'text',
  value,
  defaultValue = '',
  onChange,
  onValueChange,
  leading,
  trailing,
  allowClear,
  showCount,
  passwordToggle,
  ref,
  ...props
}: InputProps) {
  const [current, setCurrent] = useControllableState<string>({
    value: value === undefined ? undefined : String(value),
    defaultValue: String(defaultValue),
    onChange: onValueChange,
  })
  const [reveal, setReveal] = React.useState(false),
    input = React.useRef<HTMLInputElement>(null)
  React.useImperativeHandle(ref, () => input.current!)
  const field = (
    <input
      {...props}
      ref={input}
      type={passwordToggle && reveal ? 'text' : type}
      data-slot="input"
      value={current}
      onChange={(event) => {
        setCurrent(event.target.value)
        onChange?.(event)
      }}
      className={cn(
        'h-9 w-full min-w-0 rounded-md border border-input bg-transparent px-3 py-1 text-sm shadow-xs outline-none placeholder:text-muted-foreground disabled:cursor-not-allowed disabled:opacity-50 focus-visible:border-ring focus-visible:ring-2 focus-visible:ring-ring/30 aria-invalid:border-destructive',
        leading && 'pl-9',
        (trailing || allowClear || passwordToggle) && 'pr-10',
        className,
      )}
    />
  )
  if (!leading && !trailing && !allowClear && !showCount && !passwordToggle) return field
  return (
    <span className="relative inline-flex w-full flex-col">
      <span className="relative flex w-full items-center">
        {leading && <span className="absolute left-3 z-1 text-muted-foreground">{leading}</span>}
        {field}
        <span className="absolute right-2 flex items-center gap-1 text-muted-foreground">
          {allowClear && current && !props.disabled && (
            <button
              type="button"
              aria-label="Clear input"
              onClick={() => {
                const element = input.current
                if (!element) return
                Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, 'value')?.set?.call(
                  element,
                  '',
                )
                element.dispatchEvent(new Event('input', { bubbles: true }))
                setCurrent('')
                element.focus()
              }}
            >
              <X size={14} />
            </button>
          )}
          {passwordToggle && (
            <button
              type="button"
              aria-label={reveal ? 'Hide password' : 'Show password'}
              onClick={() => setReveal((v) => !v)}
            >
              {reveal ? <EyeOff size={15} /> : <Eye size={15} />}
            </button>
          )}
          {trailing}
        </span>
      </span>
      {showCount && (
        <span className="mt-1 self-end text-[10px] text-muted-foreground">
          {current.length}
          {props.maxLength ? ` / ${props.maxLength}` : ''}
        </span>
      )}
    </span>
  )
}
export function OTPInput({
  value,
  defaultValue = '',
  onValueChange,
  length = 6,
  disabled,
  pattern = /\d/,
}: {
  value?: string
  defaultValue?: string
  onValueChange?: (code: string) => void
  length?: number
  disabled?: boolean
  pattern?: RegExp
}) {
  const [code, setCode] = useControllableState({ value, defaultValue, onChange: onValueChange })
  const refs = React.useRef<(HTMLInputElement | null)[]>([])
  const clean = (text: string) =>
    Array.from(text)
      .filter((char) => {
        pattern.lastIndex = 0
        return pattern.test(char)
      })
      .join('')
      .slice(0, length)
  return (
    <div
      role="group"
      aria-label="One-time code"
      className="flex gap-2"
      onPaste={(e) => {
        e.preventDefault()
        const text = clean(e.clipboardData.getData('text'))
        setCode(text)
        refs.current[Math.min(text.length, length - 1)]?.focus()
      }}
    >
      {Array.from({ length }, (_, index) => (
        <input
          key={index}
          ref={(el) => {
            refs.current[index] = el
          }}
          aria-label={`Code digit ${index + 1}`}
          inputMode="numeric"
          autoComplete={index === 0 ? 'one-time-code' : 'off'}
          value={code[index] ?? ''}
          disabled={disabled}
          maxLength={1}
          className="h-11 w-9 rounded-lg border bg-background text-center font-mono text-lg outline-ring"
          onChange={(e) => {
            const char = clean(e.target.value).slice(-1)
            setCode((code.slice(0, index) + char + code.slice(index + 1)).slice(0, length))
            if (char) refs.current[Math.min(index + 1, length - 1)]?.focus()
          }}
          onKeyDown={(e) => {
            if (e.key === 'Backspace') {
              if (!code[index]) refs.current[Math.max(0, index - 1)]?.focus()
              else setCode(code.slice(0, index) + code.slice(index + 1))
            }
            if (e.key === 'ArrowLeft') refs.current[Math.max(0, index - 1)]?.focus()
            if (e.key === 'ArrowRight') refs.current[Math.min(length - 1, index + 1)]?.focus()
          }}
        />
      ))}
    </div>
  )
}

import { clsx, type ClassValue } from 'clsx'
import { twMerge } from 'tailwind-merge'
export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs))
}

import * as React from 'react'
import { breakpoints, type Breakpoint } from '@/lib/responsive'
export function useControllableState<T>({
  value,
  defaultValue,
  onChange,
}: {
  value?: T
  defaultValue: T
  onChange?: (value: T) => void
}) {
  const [internal, setInternal] = React.useState(defaultValue)
  const current = value === undefined ? internal : value
  const currentRef = React.useRef(current),
    valueRef = React.useRef(value),
    changeRef = React.useRef(onChange)
  currentRef.current = current
  valueRef.current = value
  changeRef.current = onChange
  const set = React.useCallback((next: T | ((previous: T) => T)) => {
    const previous = currentRef.current
    const result = typeof next === 'function' ? (next as (previous: T) => T)(previous) : next
    if (Object.is(previous, result)) return
    currentRef.current = result
    if (valueRef.current === undefined) setInternal(result)
    changeRef.current?.(result)
  }, [])
  return [current, set] as const
}
export function useMediaQuery(query: string) {
  const [matches, setMatches] = React.useState(
    () => typeof window !== 'undefined' && window.matchMedia(query).matches,
  )
  React.useEffect(() => {
    const m = window.matchMedia(query)
    const update = () => setMatches(m.matches)
    update()
    m.addEventListener('change', update)
    return () => m.removeEventListener('change', update)
  }, [query])
  return matches
}
export function useDebouncedValue<T>(value: T, delay = 250) {
  const [debounced, set] = React.useState(value)
  React.useEffect(() => {
    const id = setTimeout(() => set(value), delay)
    return () => clearTimeout(id)
  }, [value, delay])
  return debounced
}
export async function copyToClipboard(text: string) {
  await navigator.clipboard.writeText(text)
}
export function useBreakpoints() {
  const [width, setWidth] = React.useState(() =>
    typeof window === 'undefined' ? 0 : window.innerWidth,
  )
  React.useEffect(() => {
    const update = () => setWidth(window.innerWidth)
    window.addEventListener('resize', update)
    return () => window.removeEventListener('resize', update)
  }, [])
  return Object.fromEntries(
    Object.entries(breakpoints).map(([key, min]) => [key, width >= min]),
  ) as Record<Breakpoint, boolean>
}

import type { CSSProperties } from 'react'
export const breakpoints = { xs: 0, sm: 640, md: 768, lg: 1024, xl: 1280, '2xl': 1536 } as const
export type Breakpoint = keyof typeof breakpoints
export type Responsive<T> = T | Partial<Record<Breakpoint, T>>
export function responsiveStyle<T>(value: Responsive<T> | undefined, name: string): CSSProperties {
  if (value === undefined) return {}
  const values = typeof value === 'object' && value !== null ? value : { xs: value }
  return Object.fromEntries(
    Object.entries(values).map(([key, v]) => [`--${name}-${key}`, v]),
  ) as CSSProperties
}
export const responsiveCSS = Object.entries(breakpoints)
  .map(([, min], index) => {
    const fallback = (name: string, initial: string) =>
      Object.keys(breakpoints)
        .slice(0, index + 1)
        .reduce((result, key) => `var(--${name}-${key},${result})`, initial)
    return `@media(min-width:${min}px){.ergon-col{width:calc(${fallback('span', '24')} / 24 * 100%);margin-inline-start:calc(${fallback('offset', '0')} / 24 * 100%);order:${fallback('order', '0')}}.ergon-flex{gap:${fallback('gap', '12px')};flex-direction:${fallback('direction', 'row')}}}`
  })
  .join('')
